using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using RAWSelectionAssistant.ViewModels;using RAWSelectionAssistant.Core.Services.Projects;
namespace RAWSelectionAssistant.Views;
public partial class PhotoGradePageView
{
 private void R55CompareMenu(object sender,RoutedEventArgs e){var menu=new ContextMenu();void Add(string name,System.Action action){var item=new MenuItem{Header=name};item.Click+=(_,_)=>action();menu.Items.Add(item);}Add("变体比较",()=>R53MultiCompare(this,new()));Add("剧照比较",()=>{if(r54SelectedStill is not null)R54CompareStill(r54SelectedStill);});Add("灯箱观片  Ctrl+L",()=>OpenViewingTable(this,new()));menu.PlacementTarget=(UIElement)sender;menu.IsOpen=true;}
 private Point? viewingDragStart;
 private static T? TrayParent<T>(DependencyObject? value)where T:DependencyObject{while(value is not null){if(value is T t)return t;value=VisualTreeHelper.GetParent(value);}return null;}
 private void InitializeR55Tray(){R53InlineVariants.ContextMenu=new ContextMenu();R53InlineVariants.ContextMenuOpening+=(_,_)=>{if(model?.ActiveTarget is not{} target||R53InlineVariants.SelectedItem is not StudioEditVersion version)return;var menu=new ContextMenu();var item=new MenuItem{Header=model.IsViewingPinned(target.Id,version.Id)?"已上台":"固定到灯箱"};item.Click+=async(_,_)=>{model.PinViewingVariant(target.Id,version.Id);if(!ViewingMode)await ToggleViewingTableAsync();else await viewingTable!.RefreshAsync();};menu.Items.Add(item);R53InlineVariants.ContextMenu=menu;};PhotoStrip.ContextMenu=new ContextMenu();PhotoStrip.PreviewMouseLeftButtonDown+=(_,e)=>viewingDragStart=e.GetPosition(PhotoStrip);PhotoStrip.PreviewMouseMove+=(_,e)=>{if(!ViewingMode||e.LeftButton!=MouseButtonState.Pressed||viewingDragStart is not{} point||(e.GetPosition(PhotoStrip)-point).Length<5)return;var item=TrayParent<ListBoxItem>(e.OriginalSource as DependencyObject);if(item?.DataContext is not ReferenceTargetItem target||target.ActiveEditVersionId is not Guid version)return;viewingDragStart=null;DragDrop.DoDragDrop(PhotoStrip,new DataObject("Guangjing.FixedVariant",(target.Id,version)),DragDropEffects.Copy);};PhotoStrip.ContextMenuOpening+=(_,e)=>{var item=TrayParent<ListBoxItem>(Mouse.DirectlyOver as DependencyObject);var target=item?.DataContext as ReferenceTargetItem??model?.ActiveTarget;if(target is null||target.ActiveEditVersionId is not Guid version||model is null)return;var menu=new ContextMenu();var pin=new MenuItem{Header=model.IsViewingPinned(target.Id,version)?"已上台 · 固定变体":"固定到灯箱"};pin.Click+=async(_,_)=>{model.PinViewingVariant(target.Id,version);if(!ViewingMode)await ToggleViewingTableAsync();else await viewingTable!.RefreshAsync();};menu.Items.Add(pin);PhotoStrip.ContextMenu=menu;};}
}
public sealed class ViewingPinnedBadgeConverter:System.Windows.Data.IMultiValueConverter
{
 public object Convert(object[] values,System.Type type,object parameter,System.Globalization.CultureInfo culture){if(values.Length<3||values[0] is not ReferenceTargetItem target||values[1] is not Guid variant||values[2] is not ColorStudioLayout layout)return "";return layout.ViewingTable?.Items.Any(i=>i.TargetId==target.Id&&i.VariantId==variant)==true?"已上台":"";}
 public object[] ConvertBack(object value,System.Type[] types,object parameter,System.Globalization.CultureInfo culture)=>throw new System.NotSupportedException();
}
